/**
 * Multi-value HMAC secret cases shared by the July and control-plane
 * suites, so both sides split a named secret and admit a delivery the same
 * way.
 *
 * Pure data: server-shared loads this module without importing July runtime
 * code into the control plane.
 */
export const HMAC_SECRET_VECTOR_BODY = '{"event":{"id":"evt-1"}}';
const thirtyTwo = [
    "secret-0",
    ...Array.from({ length: 31 }, (_, index) => `secret-${index + 1}`),
];
const thirtyThree = [...thirtyTwo, "secret-32"];
export const HMAC_SECRET_PARSE_VECTORS = [
    { name: "empty value", raw: "", expected: "unset" },
    { name: "single value is used byte-for-byte", raw: "  alpha  ", expected: ["  alpha  "] },
    { name: "two values", raw: "alpha\nbeta", expected: ["alpha", "beta"] },
    { name: "CRLF and lone CR", raw: "alpha\r\nbeta\rgamma", expected: ["alpha", "beta", "gamma"] },
    {
        name: "trims each line and drops blank lines",
        raw: "\n  alpha \n\n\t\nbeta\t\n",
        expected: ["alpha", "beta"],
    },
    { name: "single value with a trailing newline", raw: "alpha\n", expected: ["alpha"] },
    { name: "only blank lines", raw: "\n \n\t\n", expected: "unset" },
    { name: "exactly the cap", raw: thirtyTwo.join("\n"), expected: thirtyTwo },
    { name: "one over the cap", raw: thirtyThree.join("\n"), expected: "too_many_values" },
];
export const HMAC_SECRET_MATCH_VECTORS = [
    {
        name: "single secret, single signature",
        secretValue: "alpha",
        entries: [{ signWith: "alpha" }],
        prefix: "sha256=",
        admits: true,
    },
    {
        name: "second of two secrets verifies",
        secretValue: "alpha\nbeta",
        entries: [{ signWith: "beta" }],
        prefix: "sha256=",
        admits: true,
    },
    {
        name: "secret absent from the list",
        secretValue: "alpha\nbeta",
        entries: [{ signWith: "gamma" }],
        prefix: "sha256=",
        admits: false,
    },
    {
        name: "a listed secret's line is matched trimmed",
        secretValue: "alpha\n   beta   \n",
        entries: [{ signWith: "beta" }],
        prefix: "sha256=",
        admits: true,
    },
    {
        name: "any signature under any secret",
        secretValue: "alpha\nbeta",
        entries: [{ signWith: "gamma" }, { literal: "v1=zz" }, { signWith: "beta" }],
        prefix: "v1=",
        separator: ",",
        admits: true,
    },
    {
        name: "no signature under any secret",
        secretValue: "alpha\nbeta",
        entries: [{ signWith: "gamma" }, { signWith: "delta" }],
        prefix: "v1=",
        separator: ",",
        admits: false,
    },
    {
        name: "a whole multi-line value is never itself the key",
        secretValue: "alpha\nbeta",
        entries: [{ signWith: "alpha\nbeta" }],
        prefix: "sha256=",
        admits: false,
    },
    {
        name: "over the cap admits nothing, even a listed secret",
        secretValue: thirtyThree.join("\n"),
        entries: [{ signWith: "secret-0" }],
        prefix: "sha256=",
        admits: false,
    },
];
